// Three 0.185.1 SMAA lookup pixels; MIT; see THREE-LICENSE.txt.
const entries = [
  {
    url: 'data:image/png;base64,',
    width: 160,
    height: 560,
    data: '',
  },
  {
    url: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEIAAAAhCAAAAABIXyLAAAAAOElEQVRIx2NgGAWjYBSMglEwEICREYRgFBZBqDCSLA2MGPUIVQETE9iNUAqLR5gIeoQKRgwXjwAAGn4AtaFeYLEAAAAASUVORK5CYII=',
    width: 66,
    height: 33,
    data: '',
  },
];
export function sourceImages() {
  const result = {},
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  for (const entry of entries) {
    const pixels = [];
    let bits = 0,
      accumulator = 0;
    for (let i = 0; i < entry.data.length; ++i) {
      const value = alphabet.indexOf(entry.data[i]);
      if (value < 0) break;
      accumulator = (accumulator << 6) | value;
      bits += 6;
      if (bits >= 8) {
        bits -= 8;
        pixels.push((accumulator >>> bits) & 255);
      }
    }
    result[entry.url] = {
      width: entry.width,
      height: entry.height,
      pixels: new Uint8Array(pixels),
    };
  }
  return result;
}
